"use client"

import * as React from "react"
import { Sign, type SignProps } from "@/components/ui/sign"
import type { SignShape } from "@/lib/0db/sign-shapes"

const shape: SignShape = {
  "word": "shell",
  "line": [
    [
      [
        "M",
        12,
        19
      ],
      [
        "L",
        20,
        19
      ]
    ],
    [
      [
        "M",
        4,
        17
      ],
      [
        "L",
        10,
        11
      ]
    ],
    [
      [
        "M",
        10,
        11
      ],
      [
        "L",
        4,
        5
      ]
    ]
  ]
}

function SignTerminalDots(props: Omit<SignProps, "shape" | "variant">) {
  return <Sign shape={shape} variant="dots" {...props} />
}

export { SignTerminalDots, shape }
